      "prob_desc": "இந்தியாவில் பொது அமைப்புகளால் வெளியிடப்படும் 38% க்கும் மேற்பட்ட தொழில்நுட்ப விவரக்குறிப்புகள் தவறுதலாக காலாவதியான தரநிலைகள் அல்லது முழுமையற்ற சோதனை விதிகளைக் குறிப்பிடுகின்றன, இது திட்டங்களை தணிக்கை சிக்கல்களுக்கு ஆளாக்குகிறது.",
